import assert from "node:assert/strict";
import { performance } from "node:perf_hooks";
import { createPersonMonthHoursIndex, personMonthHours } from "../shared/actual-units.ts";
import { createPersonMonthHoursIndex as previousIndex, personMonthHours as previousPersonMonthHours } from "./baseline-actual-units.ts";
import fs from "node:fs/promises";
const resources=Array.from({length:80},(_,i)=>"r"+i), months=Array.from({length:9},(_,i)=>"2026-"+String(i+1).padStart(2,"0"));
const data={workCalendar:{},personCalendar:{},actualWorkedHours:{}};
for(const month of months){data.workCalendar[month+"-01"]={fraction:1}; data.workCalendar[month+"-02"]={fraction:.5}; for(const r of resources){data.actualWorkedHours[r+"|"+month]=230;data.personCalendar[r+"|"+month+"-03|leave"]={type:"leave",hours:2};}}
const tasks={previousIndex:()=>previousIndex(data),currentIndex:()=>createPersonMonthHoursIndex(data),previousDirect:()=>({get:(r,m)=>previousPersonMonthHours(m,r,data.actualWorkedHours[r+"|"+m],data.workCalendar,data.personCalendar)}),currentDirect:()=>({get:(r,m)=>personMonthHours(m,r,data.actualWorkedHours[r+"|"+m],data.workCalendar,data.personCalendar)})};
const samples=Object.fromEntries(Object.keys(tasks).map(k=>[k,[]]));
for(let n=0;n<24;n++){const keys=n%2?Object.keys(tasks).reverse():Object.keys(tasks);for(const key of keys){const start=performance.now(),index=tasks[key]();let total=0;for(const month of months)for(const r of resources)total+=index.get(r,month).effectiveHours;if(n>=4)samples[key].push(performance.now()-start);assert(total>0);}}
const percentile=(a,p)=>[...a].sort((x,y)=>x-y)[Math.ceil(a.length*p)-1];
const summary=Object.fromEntries(Object.entries(samples).map(([k,a])=>[k,{count:a.length,medianMs:percentile(a,.5),sampleP95Ms:percentile(a,.95)}]));
await fs.writeFile('.reference/month-benchmark.json',JSON.stringify({scope:"Pure synthetic helpers, 80 employees x 9 months, alternating order, 4 warmups, 20 samples; no DB/HTTP/capacity claim",samples,summary},null,2)+'\n');console.log(JSON.stringify(summary,null,2));

