import { Store } from "../backend/store.mjs";
import { seedBenchmarkStore } from "../scripts/benchmark-fixture.mjs";
import { validate as current } from "../shared/server-domain.ts";
import { validate as previous } from "./baseline-shared/server-domain.ts";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import assert from "node:assert/strict";
import { performance } from "node:perf_hooks";
const dir=await fs.mkdtemp(path.join(os.tmpdir(),"aa-month-validation-bench-"));
const store=new Store({env:{NODE_ENV:"test",DB_PROVIDER:"sqljs",SQLJS_FILE:path.join(dir,"synthetic.sqlite")}});
try{
 await store.connect();await seedBenchmarkStore(store,10000,{resources:80,actuals:4000,percentages:4000,calendarDays:1000});
 const {data}=await store.read(), input=structuredClone(data), expected=previous(data);
 assert.deepEqual(current(data),expected);assert.deepEqual(data,input);
 const samples={previous:[],current:[]};
 for(let n=0;n<24;n++)for(const key of n%2?["current","previous"]:["previous","current"]){const start=performance.now();const value=(key==="previous"?previous:current)(data);const elapsed=performance.now()-start;if(n>=4)samples[key].push(elapsed);assert.equal(Object.keys(value.allocations).length,10000);}
 assert.deepEqual(data,input);
 const percentile=(a,p)=>[...a].sort((x,y)=>x-y)[Math.ceil(a.length*p)-1];
 const summary=Object.fromEntries(Object.entries(samples).map(([k,a])=>[k,{count:a.length,medianMs:percentile(a,.5),sampleP95Ms:percentile(a,.95)}]));
 await fs.writeFile('.reference/full-validation-benchmark.json',JSON.stringify({scope:"Full pure validate on a synthetic SQL.js snapshot, 10000 planned/4000 actual/4000 percentages/80 employees/1000 leave days; alternate order, 4 warmups, 20 samples; no HTTP/SQL Server/capacity claim",summary,samples,fullOutputEqual:true,inputUnchanged:true},null,2)+'\n');console.log(JSON.stringify(summary,null,2));
}finally{await store.close();await fs.rm(dir,{recursive:true,force:true});}
